function BookCoverPasteSpatulaMaker.init() BookCoverPasteSpatulaMaker.ironStock=12; BookCoverPasteSpatulaMaker.bronzeStock=10; BookCoverPasteSpatulaMaker.woodStock=16; BookCoverPasteSpatulaMaker.leatherStock=10; BookCoverPasteSpatulaMaker.silverStock=8; BookCoverPasteSpatulaMaker.goldStock=6; BookCoverPasteSpatulaMaker.jewelStock=4; BookCoverPasteSpatulaMaker.pearlStock=4; BookCoverPasteSpatulaMaker.productStock={}; BookCoverPasteSpatulaMaker.buildings={}; BookCoverPasteSpatulaMaker.maker=nil; BookCoverPasteSpatulaMaker.activeMaking={}; BookCoverPasteSpatulaMaker.totalProducts=0; BookCoverPasteSpatulaMaker.dayTimer=0; print("[BookCoverPasteSpatulaMaker] Royal Book Cover Paste Spatula Maker System initialized (6 products, 4 buildings)") end
function BookCoverPasteSpatulaMaker.hireMaker(n,s) s=s or math.random(55,90); local c=575+s*12; if not _G.state or (_G.state.gold or 0)<c then return false,"Premalo zlata" end; _G.state.gold=_G.state.gold-c; BookCoverPasteSpatulaMaker.maker={name=n or ("Lopatičar "..math.random(1,99)),skill=s,hiredDay=os.time(),itemsMade=0}; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Lopatičar najet: %s (spretnost: %d)",BookCoverPasteSpatulaMaker.maker.name,s),"success") end; return true end
function BookCoverPasteSpatulaMaker.canBuild(id) local d=BUILDINGS[id]; if not d then return false,"Neznana zgradba" end; if not _G.state then return false,"Brez stanja" end; if _G.state.gold<(d.cost.gold or 0) then return false,"Premalo zlata" end; if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" and (_G.state.resources[r] or 0)<a then return false,"Premalo "..r end end end; return true end
function BookCoverPasteSpatulaMaker.build(id) local ok,e=BookCoverPasteSpatulaMaker.canBuild(id); if not ok then return false,e end; local d=BUILDINGS[id]; _G.state.gold=_G.state.gold-(d.cost.gold or 0); if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" then _G.state.resources[r]=(_G.state.resources[r] or 0)-a end end end; table.insert(BookCoverPasteSpatulaMaker.buildings,{type=id,builtDay=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,"Zgrajeno: "..d.name,"success") end; return true end
function BookCoverPasteSpatulaMaker.getQualityBonus() local b=0; for _,bd in ipairs(BookCoverPasteSpatulaMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.qualityBonus then b=b+d.qualityBonus end end; return b end
function BookCoverPasteSpatulaMaker.canMake(pt) local d=PRODUCTS[pt]; if not d then return false,"Neznan produkt" end; if d.ironCost and BookCoverPasteSpatulaMaker.ironStock<(d.ironCost or 0) then return false,"Premalo železa" end; if d.bronzeCost and BookCoverPasteSpatulaMaker.bronzeStock<(d.bronzeCost or 0) then return false,"Premalo brona" end; if d.woodCost and BookCoverPasteSpatulaMaker.woodStock<(d.woodCost or 0) then return false,"Premalo lesa" end; if d.leatherCost and BookCoverPasteSpatulaMaker.leatherStock<(d.leatherCost or 0) then return false,"Premalo usnja" end; if d.silverCost and BookCoverPasteSpatulaMaker.silverStock<(d.silverCost or 0) then return false,"Premalo srebra" end; if d.goldCost and BookCoverPasteSpatulaMaker.goldStock<(d.goldCost or 0) then return false,"Premalo zlata" end; if d.jewelCost and BookCoverPasteSpatulaMaker.jewelStock<(d.jewelCost or 0) then return false,"Premalo draguljev" end; if d.pearlCost and BookCoverPasteSpatulaMaker.pearlStock<(d.pearlCost or 0) then return false,"Premalo biserov" end; if #BookCoverPasteSpatulaMaker.buildings==0 then return false,"Potrebna lopaticna delavnica" end; if not BookCoverPasteSpatulaMaker.maker then return false,"Potreben lopaticar" end; return true end
function BookCoverPasteSpatulaMaker.make(pt,qty) qty=qty or 1; local ok,e=BookCoverPasteSpatulaMaker.canMake(pt); if not ok then return false,e end; local d=PRODUCTS[pt]; if d.ironCost then BookCoverPasteSpatulaMaker.ironStock=BookCoverPasteSpatulaMaker.ironStock-d.ironCost*qty end; if d.bronzeCost then BookCoverPasteSpatulaMaker.bronzeStock=BookCoverPasteSpatulaMaker.bronzeStock-d.bronzeCost*qty end; if d.woodCost then BookCoverPasteSpatulaMaker.woodStock=BookCoverPasteSpatulaMaker.woodStock-d.woodCost*qty end; if d.leatherCost then BookCoverPasteSpatulaMaker.leatherStock=BookCoverPasteSpatulaMaker.leatherStock-d.leatherCost*qty end; if d.silverCost then BookCoverPasteSpatulaMaker.silverStock=BookCoverPasteSpatulaMaker.silverStock-d.silverCost*qty end; if d.goldCost then BookCoverPasteSpatulaMaker.goldStock=BookCoverPasteSpatulaMaker.goldStock-d.goldCost*qty end; if d.jewelCost then BookCoverPasteSpatulaMaker.jewelStock=BookCoverPasteSpatulaMaker.jewelStock-d.jewelCost*qty end; if d.pearlCost then BookCoverPasteSpatulaMaker.pearlStock=BookCoverPasteSpatulaMaker.pearlStock-d.pearlCost*qty end; local t=d.time; if BookCoverPasteSpatulaMaker.maker then t=math.max(1,t-math.floor(BookCoverPasteSpatulaMaker.maker.skill/13)) end; table.insert(BookCoverPasteSpatulaMaker.activeMaking,{id="bookcoverpastespatula_"..tostring(os.time()).."_"..tostring(math.random(1000,9999)),productType=pt,productName=d.name,cost=d.cost*qty,quantity=qty,food=0,prestige=d.prestige or 0,happiness=d.happiness or 0,daysRemaining=t,started=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Izdelava: %d %s (%d dni)",qty,d.name,t),"info") end; return true end
function BookCoverPasteSpatulaMaker.completeMaking(m) local q=1.0+(BookCoverPasteSpatulaMaker.getQualityBonus()/100); if BookCoverPasteSpatulaMaker.maker then q=q+(BookCoverPasteSpatulaMaker.maker.skill/140) end; q=math.min(2.5,q); BookCoverPasteSpatulaMaker.productStock[m.productType]=(BookCoverPasteSpatulaMaker.productStock[m.productType] or 0)+m.quantity; BookCoverPasteSpatulaMaker.totalProducts=BookCoverPasteSpatulaMaker.totalProducts+m.quantity; if m.prestige>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.prestige) end; if m.happiness>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.happiness) end; if BookCoverPasteSpatulaMaker.maker then BookCoverPasteSpatulaMaker.maker.itemsMade=BookCoverPasteSpatulaMaker.maker.itemsMade+m.quantity; if math.random()<0.25 then BookCoverPasteSpatulaMaker.maker.skill=math.min(100,BookCoverPasteSpatulaMaker.maker.skill+1) end end; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Lopatica izdelan: %d %s (kakovost: %.1f)",m.quantity,m.productName,q),"success") end; if _G.GameEventBus then pcall(_G.GameEventBus.publish,"bookcoverpastespatula.completed",{productName=m.productName,prestige=m.prestige,happiness=m.happiness}) end end
function BookCoverPasteSpatulaMaker.update(dt) if not _G.state then return end; BookCoverPasteSpatulaMaker.dayTimer=BookCoverPasteSpatulaMaker.dayTimer+dt; if BookCoverPasteSpatulaMaker.dayTimer>=30 then BookCoverPasteSpatulaMaker.dayTimer=0; for i=#BookCoverPasteSpatulaMaker.activeMaking,1,-1 do local m=BookCoverPasteSpatulaMaker.activeMaking[i]; m.daysRemaining=m.daysRemaining-1; if m.daysRemaining<=0 then BookCoverPasteSpatulaMaker.completeMaking(m); table.remove(BookCoverPasteSpatulaMaker.activeMaking,i) end end; local tu=0; for _,bd in ipairs(BookCoverPasteSpatulaMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.upkeep then tu=tu+d.upkeep end end; if BookCoverPasteSpatulaMaker.maker then tu=tu+15 end; if tu>0 and _G.state then _G.state.gold=math.max(0,(_G.state.gold or 0)-tu) end end end
function BookCoverPasteSpatulaMaker.getStats() return {ironStock=BookCoverPasteSpatulaMaker.ironStock,bronzeStock=BookCoverPasteSpatulaMaker.bronzeStock,woodStock=BookCoverPasteSpatulaMaker.woodStock,leatherStock=BookCoverPasteSpatulaMaker.leatherStock,silverStock=BookCoverPasteSpatulaMaker.silverStock,goldStock=BookCoverPasteSpatulaMaker.goldStock,jewelStock=BookCoverPasteSpatulaMaker.jewelStock,pearlStock=BookCoverPasteSpatulaMaker.pearlStock,productStock=BookCoverPasteSpatulaMaker.productStock,numBuildings=#BookCoverPasteSpatulaMaker.buildings,hasMaker=BookCoverPasteSpatulaMaker.maker~=nil,makerName=BookCoverPasteSpatulaMaker.maker and BookCoverPasteSpatulaMaker.maker.name or "—",makerSkill=BookCoverPasteSpatulaMaker.maker and BookCoverPasteSpatulaMaker.maker.skill or 0,activeMaking=#BookCoverPasteSpatulaMaker.activeMaking,totalProducts=BookCoverPasteSpatulaMaker.totalProducts} end
